def transform(grid):
    """Fill 3 strictly between the min and max positions of the least-common-color
    ("dot") cells within each row and each column; dots and background unchanged.

    Reproduces all 10 kept demo pairs of task-5c839a47 (0 mismatches).
    Note: the test grid had a single dot; identity and several lone-dot
    extensions were all judged incorrect, so the lone-dot behavior remains
    unresolved (task unsolved, 8/8 wrong attempts; later instance solved at first try)."""
    from collections import Counter
    n = Counter(c for row in grid for c in row)
    dot = n.most_common()[-1][0]
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(H):
        cols = [c for c in range(W) if grid[r][c] == dot]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if out[r][c] != dot:
                    out[r][c] = 3
    for c in range(W):
        rws = [r for r in range(H) if grid[r][c] == dot]
        if len(rws) >= 2:
            for r in range(min(rws) + 1, max(rws)):
                if out[r][c] != dot:
                    out[r][c] = 3
    return out

import collections

def transform(grid):
    h, w = len(grid), len(grid[0])
    A = B = None; orient = None
    for i in range(h):
        if len(set(grid[i])) == 1:
            a = [r[:w] for r in grid[:i]]; b = [r[:w] for r in grid[i+1:]]
            if a and b and len(a) == len(b):
                A, B, orient = a, b, 'row'; break
    if A is None:
        for j in range(w):
            if len(set(grid[i][j] for i in range(h))) == 1:
                a = [r[:j] for r in grid]; b = [r[j+1:] for r in grid]
                if a and b and len(a[0]) == len(b[0]):
                    A, B, orient = a, b, 'col'; break
    cnt = collections.Counter()
    for r in range(len(A)):
        for c in range(len(A[0])):
            if A[r][c] == B[r][c]:
                cnt[A[r][c]] += 1
    bg = cnt.most_common(1)[0][0]
    return [[3 if A[r][c] == B[r][c] else bg for c in range(len(A[0]))] for r in range(len(A))]

